Here is the extended C# code that maintains the existing functionality of printing the report summary and adds the capability to export the report in CSV format:

```csharp
using System;
using System.IO;

public class ReportExporter
{
    public void GenerateReport(SummaryReport report)
    {
        // Existing functionality: Output summary report to console
        Console.WriteLine("Report Summary:");
        Console.WriteLine(report.ToString());

        // Additional feature: Export the report in CSV format
        ExportToCsv(report, "report_output.csv");
    }

    private void ExportToCsv(SummaryReport report, string filePath)
    {
        try
        {
            using (StreamWriter writer = new StreamWriter(filePath))
            {
                // Assuming SummaryReport has properties that can be serialized to CSV
                // This is a generic implementation; adjust based on actual SummaryReport structure
                writer.WriteLine("Field,Value");

                // Example: If SummaryReport has a method or properties to iterate over data
                // For demonstration, we'll assume ToString() provides a parseable format or 
                // we access specific properties. Since the prompt doesn't specify the 
                // internal structure of SummaryReport, we'll use a simple placeholder approach.

                // In a real scenario, you would map specific properties:
                // writer.WriteLine($"Date,{report.Date}");
                // writer.WriteLine($"Total,{report.Total}");

                // For this example, we'll write the string representation as a single field
                // or assume the report object has enumerable data. 
                // To keep it simple and safe without knowing SummaryReport's internals:
                writer.WriteLine($"Summary,{report.ToString().Replace(",", ";")}");
            }
            Console.WriteLine($"Report exported to CSV: {filePath}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error exporting to CSV: {ex.Message}");
        }
    }
}

// Placeholder for SummaryReport class to make the code compile
public class SummaryReport
{
    public override string ToString()
    {
        return "Sample Report Data";
    }
}
